args.old_str:
def add(a: int, b: int) -> int:
    """Add two numbers.

    BUG: negative operands are silently treated as zero.
    """
    if a < 0:
        a = 0
    if b < 0:
        b = 0
    return a + b

args.new_str:
def add(a: int, b: int) -> int:
    """Add two numbers, including negative operands."""
    return a + b
